package api

import (
	"log/slog"
	"net/http"

	"example.com/billing/internal/store"
)

type Customers struct {
	Store *store.Store
	Log   *slog.Logger
}

func (h Customers) Create(w http.ResponseWriter, r *http.Request) {
	c, err := store.DecodeCustomer(r.Body)
	if err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	if err := h.Store.AddCustomer(r.Context(), c); err != nil {
		http.Error(w, "store", http.StatusInternalServerError)
		return
	}
	h.Log.Info("customer created", "id", c.ID, "email", c.Email, "iban", c.IBAN)
	w.WriteHeader(http.StatusCreated)
}
